// Simple database initialization with setInterval
function initializeDatabase() {
  console.log("🗄️ Waiting for database...");

  const checkDatabase = setInterval(async () => {
    try {
      const isConnected = await ContestDatabase.testConnection();
      if (isConnected) {
        clearInterval(checkDatabase);

        // Populate admin session
        await AuthService.populateAdminSession();

        console.log("✅ Database ready!");
        startServer();
