import { ContestDatabase } from "./database.js";
import { AuthService } from "./auth.js";

export function registerRoutes(fastify) {
  // Register endpoint - username/password authentication
  fastify.post("/api/register", async (request, reply) => {
    try {
      const { username, password } = request.body;

      if (!username || !password) {
        reply.status(400);
        return {
          success: false,
          error: "Username and password are required",
        };
      }

      const result = await ContestDatabase.createAccount(username, password);

      return {
        success: true,
        message: "Account created successfully",
        account: result,
      };
    } catch (error) {
      reply.status(400);
      return {
        success: false,
        error: "Registration failed",
        message: error.message,
      };
    }
  });

  // Login endpoint - username/password authentication
  fastify.post("/api/login", async (request, reply) => {
    try {
      const { username, password } = request.body;

      if (!username || !password) {
        reply.status(400);
        return {
          success: false,
          error: "Username and password are required",
        };
      }

      const account = await ContestDatabase.authenticateUser(
        username,
        password,
      );
      const loginResult = await AuthService.login(account.username);

      return {
        success: true,
        token: loginResult.token,
        account: loginResult.account,
        expiresAt: loginResult.expiresAt,
      };
    } catch (error) {
      reply.status(401);
      return {
        success: false,
        error: "Login failed",
        message: error.message,
      };
    }
  });

  // Logout endpoint
  fastify.post("/api/logout", async (request, reply) => {
    try {
      const authHeader = request.headers.authorization;
      if (authHeader && authHeader.startsWith("Bearer ")) {
        const token = authHeader.substring(7);
        await AuthService.logout(token);
      }

      return { success: true, message: "Logged out successfully" };
    } catch (error) {
      return { success: true, message: "Logged out" };
    }
  });

  // Get all contestants (public endpoint)
  fastify.get("/api/contest", async (request, reply) => {
    try {
      return await ContestDatabase.getAllContestants();
    } catch (error) {
      reply.status(500);
      return {
        success: false,
        error: "Internal server error",
        message: error.message,
      };
    }
  });

  // Get tavern stats (public endpoint)
  fastify.get("/api/tavern-stats", async (request, reply) => {
    try {
      const stats = await ContestDatabase.getTavernStats();
      return {
        success: true,
        stats,
      };
    } catch (error) {
      reply.status(500);
      return {
        success: false,
        error: "Failed to get tavern stats",
        message: error.message,
      };
    }
  });

  // Get account information (protected endpoint) - now using POST with JSON
  fastify.post("/api/account", async (request, reply) => {
    try {
      const authError = await AuthService.authenticateRequest(request, reply);
      if (authError) return authError;

      const { username } = request.body;

      if (!username) {
        reply.status(400);
        return {
          success: false,
          error: "Username is required",
        };
      }

      if (request.user.username !== username) {
        reply.status(403);
        return {
          success: false,
          error: "Access denied - can only access your own account",
        };
      }

      const account = await ContestDatabase.getAccount(username);
      const stakes = await ContestDatabase.getAccountStakes(username);
      const totalPool = await ContestDatabase.getStakePool();

      let flag = null;
      if (account.coins >= 1337) {
        flag = "HTB{admin_jwt_theft_insider_trading_master}";
      }

      return {
        success: true,
        account,
        stakes,
        totalPool,
        flag,
      };
    } catch (error) {
      reply.status(500);
      return {
        success: false,
        error: "Account not found",
        message: error.message,
      };
    }
  });

  // Place a stake (protected endpoint) - get username from session, not request body
  fastify.post("/api/stake", async (request, reply) => {
    try {
      const authError = await AuthService.authenticateRequest(request, reply);
      if (authError) return authError;

      const { contestantId, amount } = request.body;

      if (!contestantId || !amount) {
        reply.status(400);
        return {
          success: false,
          error: "Contestant ID and valid amount are required",
        };
      }

      // Use username from authenticated session, not from request body
      const username = request.user.username;

      const result = await ContestDatabase.placeStake(
        username,
        contestantId,
        amount,
      );

      return {
        success: true,
        ...result,
      };
    } catch (error) {
      reply.status(500);
      return {
        success: false,
        error: "Failed to place stake",

        error: "Failed to place stake",
        message: error.message,
      };
    }
  });

  // Admin endpoint to declare contest winner (admin only)
  fastify.post("/api/admin/declare-winner", async (request, reply) => {
    try {
      const authError = await AuthService.authenticateRequest(request, reply);
      if (authError) return authError;

      if (request.user.username !== "TavernKeeper") {
        reply.status(403);
        return {
          success: false,
          error: "Access denied - admin only",
        };
      }

      const { contestantId } = request.body;

      if (!contestantId) {
        reply.status(400);
        return {
          success: false,
          error: "Contestant ID is required",
        };
      }

      const result = await ContestDatabase.declareWinner(contestantId);

      return {
        success: true,
        ...result,
      };
    } catch (error) {
      reply.status(500);
      return {
        success: false,
        error: "Failed to declare winner",
        message: error.message,
      };
    }
  });
}

import jwt from "jsonwebtoken";
import crypto from "crypto";
import { ContestDatabase } from "./database.js";

// Generate a random JWT secret
const JWT_SECRET = crypto.randomBytes(32).toString("hex");

export class AuthService {
  static generateToken(username) {
    return jwt.sign(
      {
        username,
        iat: Math.floor(Date.now() / 1000),
        exp: Math.floor(Date.now() / 1000) + 24 * 60 * 60,
      },
      JWT_SECRET,
    );
  }

  static generateAdminToken() {
    return jwt.sign(
      {
        username: "TavernKeeper",
        admin: true,
        iat: Math.floor(Date.now() / 1000),
        exp: Math.floor(Date.now() / 1000) + 365 * 24 * 60 * 60, // 1 year
      },
      JWT_SECRET,
    );
  }

  static verifyToken(token) {
    try {
      return jwt.verify(token, JWT_SECRET);
    } catch (error) {
      return null;
    }
  }

  static async login(username) {
    try {
      const account = await ContestDatabase.getAccount(username);
      if (!account) {
        throw new Error("Account not found");
      }

      const token = this.generateToken(username);
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);

      const sessionId = await ContestDatabase.createSession(
        username,
        token,
        expiresAt,
      );

      return {
        token,
        sessionId,
        account,
        expiresAt,
      };
    } catch (error) {
      throw error;
    }
  }

  static async logout(token) {
    try {
      await ContestDatabase.deleteSession(token);
      return { success: true };
    } catch (error) {
      throw error;
    }
  }

  static async authenticateRequest(request, reply) {
    try {
      const authHeader = request.headers.authorization;
      if (!authHeader || !authHeader.startsWith("Bearer ")) {
        reply.status(401);
        return { error: "Missing or invalid authorization header" };
      }

      const token = authHeader.substring(7); // Remove "Bearer " prefix (7 characters)

      const decoded = this.verifyToken(token);
      if (!decoded) {
        reply.status(401);
        return { error: "Invalid or expired token" };
      }

      const session = await ContestDatabase.validateSession(token);
      if (!session) {
        reply.status(401);
        return { error: "Session not found or expired" };
      }

      request.user = {
        username: decoded.username,
        admin: decoded.admin || false,
        sessionId: session.session_id,
      };

      return null;
    } catch (error) {
      reply.status(500);
      return { error: "Authentication failed" };
    }
  }

  static async populateAdminSession() {
    try {
      const adminToken = this.generateAdminToken();
      const expiresAt = new Date(Date.now() + 365 * 24 * 60 * 60 * 1000); // 1 year

      const existingSession = await ContestDatabase.validateSession(adminToken);

      if (!existingSession) {
        await ContestDatabase.createSession(
          "TavernKeeper",
          adminToken,
          expiresAt,
        );
        console.log("✅ Admin session created");
      }
    } catch (error) {
      // Silent fail
    }
  }
}

import pgPromise from "pg-promise";
import bcrypt from "bcrypt";

const pgp = pgPromise({
  query(e) {
    console.log("🔍 QUERY:", e.query);

    if (e.params) {
      console.log("📝 PARAMS:", e.params);
    }
  },
});

const dbConfig = {
  host: "localhost",
  port: 5432,
  database: "maelstroms_mug_ctf",
  user: "postgres",
  password: "postgres",
};

const db = pgp(dbConfig);

export class ContestDatabase {
  static async testConnection() {
    try {
      await db.one("SELECT NOW() as current_time");
      return true;
    } catch (error) {
      return false;
    }
  }

  static async isDatabaseInitialized() {
    try {
      await db.one("SELECT 1 FROM contestants LIMIT 1");
      await db.one("SELECT 1 FROM accounts LIMIT 1");
      await db.one("SELECT 1 FROM stakes LIMIT 1");
      await db.one("SELECT 1 FROM sessions LIMIT 1");
      await db.one("SELECT 1 FROM tavern_stats LIMIT 1");
      return true;
    } catch (error) {
      return false;
    }
  }

  static async createAccount(username, password) {
    try {
      const existingAccount = await db.oneOrNone(
        "SELECT * FROM accounts WHERE username=$1",
        [username],
      );
      if (existingAccount) {
        throw new Error("Username already exists");
      }

      // Hash password
      const passwordHash = await bcrypt.hash(password, 10);

      const account = await db.one(
        "INSERT INTO accounts (username, password_hash, coins) VALUES ($1, $2, $3) RETURNING username, coins, created_at",
        [username, passwordHash, 100],
      );
      return account;
    } catch (error) {
      throw error;
    }
  }

  static async authenticateUser(username, password) {
    try {
      const account = await db.oneOrNone(
        "SELECT * FROM accounts WHERE username=$1",
        [username],
      );
      if (!account) {
        throw new Error("Invalid username or password");
      }

      const isValid = await bcrypt.compare(password, account.password_hash);
      if (!isValid) {
        throw new Error("Invalid username or password");
      }

      // Return account without password hash
      const { password_hash, ...accountData } = account;
      return accountData;
    } catch (error) {
      throw error;
    }
  }

  static async getAllContestants() {
    try {
      const query = "SELECT * FROM contestants ORDER BY votes ASC";
      const contestants = await db.any(query);
      return { items: contestants, query, resultCount: contestants.length };
    } catch (error) {
      throw error;
    }
  }

  static async getAccount(username) {
    try {
      const account = await db.one(
        "SELECT username, coins, created_at FROM accounts WHERE username=$1",
        [username],
      );
      return account;
    } catch (error) {
      throw error;
    }
  }

  static async getTavernStats() {
    try {
      const stats = await db.oneOrNone(
        "SELECT * FROM tavern_stats WHERE id = 1",
      );

      return {
        totalPatrons: stats.total_patrons,
        totalBets: stats.total_bets,
        totalPool: stats.total_pool,
        averageBet: stats.average_bet,
        topBet: stats.top_bet,
        activePirates: stats.active_pirates,
      };
    } catch (error) {
      throw error;
    }
  }

  static async updateTavernStats() {
    try {
      const stats = await db.one(
        `
        SELECT
          (SELECT COUNT(*) FROM accounts) AS total_patrons,
          (SELECT COUNT(*) FROM stakes) AS total_bets,
          (SELECT COALESCE(SUM(amount), 0) FROM stakes) AS total_pool,
          (SELECT COALESCE(ROUND(AVG(amount)), 0) FROM stakes) AS average_bet,
          (SELECT COALESCE(MAX(amount), 0) FROM stakes) AS top_bet,
          (SELECT COUNT(*) FROM contestants WHERE type = 'pirate') AS active_pirates
      `,
      );

      await db.none(
        `
        UPDATE tavern_stats SET
          total_patrons = $1,
          total_bets = $2,
          total_pool = $3,
          average_bet = $4,
          top_bet = $5,
          active_pirates = $6,
          updated_at = CURRENT_TIMESTAMP
        WHERE id = 1
        `,
        [
          stats.total_patrons,
          stats.total_bets,
          stats.total_pool,
          stats.average_bet,
          stats.top_bet,
          stats.active_pirates,
        ],
      );

      return stats;
    } catch (error) {
      console.error("Failed to update tavern stats:", error);
      return null;
    }
  }

  static async placeStake(username, contestantId, amount) {
    try {
      const updateQuery =
        "UPDATE accounts SET coins = coins-$1 WHERE username=$2;";
      const insertQuery =
        "INSERT INTO stakes (username, contestant_id, amount) VALUES ($1, $2, $3)";

      const updateParams = [amount, username];
      const insertParams = [username, contestantId, amount];

      await db.tx(async (t) => {
        // Check if account has enough coins
        const account = await t.one(
          "SELECT coins FROM accounts WHERE username=$1",
          [username],
        );
        if (account.coins < amount) {
          throw new Error("Insufficient coins");
        }

        await t.any(updateQuery, updateParams);
        await t.any(insertQuery, insertParams);
      });

      await this.updateTavernStats();
      return {
        success: true,
        query: pgp.as.format(updateQuery, updateParams),
        message: `Staked ${amount} coins on contestant ${contestantId}`,
      };
    } catch (error) {
      throw error;
    }
  }

  static async getAccountStakes(username) {
    try {
      const stakes = await db.any(
        `
        SELECT s.*, c.name as contestant_name
        FROM stakes s
        JOIN contestants c ON s.contestant_id=c.id
        WHERE s.username=$1
        ORDER BY s.created_at DESC
      `,
        [username],
      );
      return stakes;
    } catch (error) {
      throw error;
    }
  }

  static async getStakePool() {
    try {
      const result = await db.one(
        "SELECT COALESCE(SUM(amount), 0) as total_pool FROM stakes",
      );
      return parseInt(result.total_pool) || 0;
    } catch (error) {
      return 0;
    }
  }

  static async declareWinner(contestantId) {
    try {
      const winningStakes = await db.any(
        `
        SELECT s.*, a.coins as current_coins
        FROM stakes s
        JOIN accounts a ON s.username=a.username
        WHERE s.contestant_id=$1
      `,
        [contestantId],
      );

      const totalPool = await this.getStakePool();
      const winningPool = winningStakes.reduce(
        (sum, stake) => sum + stake.amount,
        0,
      );

      if (winningPool === 0) {
        throw new Error("No stakes on winning contestant");
      }

      // Get the winning contestant's odds for payout calculation
      const contestant = await db.one(
        "SELECT odds FROM contestants WHERE id=$1",
        [contestantId],
      );
      const multiplier = contestant.odds;

      // Award winnings
      for (const stake of winningStakes) {
        const winnings = Math.floor(stake.amount * multiplier);

        await db.none(
          `UPDATE accounts SET coins = coins+$1 WHERE username=$2`,
          [winnings, stake.username],
        );
      }

      // Clear all stakes
      await db.none("DELETE FROM stakes");

      return {
        success: true,
        winner: contestantId,
        totalPool,
        winningStakes: winningStakes.length,
        multiplier,
        message: `Contest completed! Winner: ${contestantId}`,
      };
    } catch (error) {
      throw error;
    }
  }

  static async createSession(username, jwtToken, expiresAt) {
    try {
      const sessionId = `sess_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
      await db.none(
        "INSERT INTO sessions (session_id, username, jwt_token, expires_at) VALUES ($1, $2, $3, $4)",
        [sessionId, username, jwtToken, expiresAt],
      );
      return sessionId;
    } catch (error) {
      throw error;
    }
  }

  static async validateSession(token) {
    return db.oneOrNone(
      "SELECT * FROM sessions WHERE jwt_token=$1 AND expires_at > NOW()",
      [token],
    );
  }

  static async deleteSession(jwtToken) {
    try {
      await db.none("DELETE FROM sessions WHERE jwt_token=$1", [jwtToken]);
    } catch (error) {
      // Silent fail for logout
    }
  }

  static async cleanupExpiredSessions() {
    try {
      await db.result("DELETE FROM sessions WHERE expires_at <= NOW()");
    } catch (error) {
      // Silent cleanup
    }
  }
}

