-- Create the CTF database
CREATE DATABASE maelstroms_mug_ctf;

-- Connect to the CTF database
\c maelstroms_mug_ctf;

-- Create contestants table
CREATE TABLE contestants (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  votes INTEGER NOT NULL DEFAULT 0,
  description TEXT,
  type TEXT,
  odds DECIMAL(4,1) NOT NULL DEFAULT 2.0,
  reputation_level TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create accounts table
CREATE TABLE accounts (
  username TEXT PRIMARY KEY,
  password_hash TEXT NOT NULL,
  coins INTEGER NOT NULL DEFAULT 100,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create stakes table (no FK constraints)
CREATE TABLE stakes (
  stake_id SERIAL PRIMARY KEY,
  username TEXT,
  contestant_id TEXT,
  amount INTEGER NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create sessions table (no FK constraints)
CREATE TABLE sessions (
  session_id TEXT PRIMARY KEY,
  username TEXT,
  jwt_token TEXT NOT NULL,
  expires_at TIMESTAMP NOT NULL,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Create tavern_stats table
CREATE TABLE tavern_stats (
  id INTEGER PRIMARY KEY DEFAULT 1,
  total_patrons INTEGER NOT NULL DEFAULT 45,
  total_bets INTEGER NOT NULL DEFAULT 187,
  total_pool INTEGER NOT NULL DEFAULT 4250,
  average_bet INTEGER NOT NULL DEFAULT 52,
  top_bet INTEGER NOT NULL DEFAULT 425,
  active_pirates INTEGER NOT NULL DEFAULT 6,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Utility function to randomly seed 194 themed stakes
CREATE OR REPLACE FUNCTION populate_random_stakes()
RETURNS void AS $$
DECLARE
    usernames TEXT[] := ARRAY[
        'pegleg_pete', 'blackbeard_bob', 'rumrunner_jack', 'seawitch_sally',
        'hookhand_joe', 'sirens_song', 'barnacle_bill', 'flintlock_fiona',
        'coral_cleo', 'krakenbait_kyle', 'poopdeck_paul', 'mainsail_mary',
        'cutlass_craig', 'ghost_greta', 'doubloon_dan', 'cannonade_clara'
    ];
    contestant_ids TEXT[] := ARRAY['c1', 'c2', 'c3', 'c4', 'c5', 'c6'];
    i INT := 0;
    picked_username TEXT;
    picked_contestant TEXT;
    picked_amount INT;
BEGIN
    FOR i IN 1..194 LOOP
        picked_username := usernames[ceil(random() * array_length(usernames, 1))::INT];
        picked_contestant := contestant_ids[ceil(random() * array_length(contestant_ids, 1))::INT];
        picked_amount := floor(random() * 20 + 1)::INT; -- Amount: 1 to 20 coins

        -- Ensure the user exists (create if needed)
        PERFORM 1 FROM accounts WHERE username = picked_username;
        IF NOT FOUND THEN
            INSERT INTO accounts (username, password_hash, coins)
            VALUES (
                picked_username,
                '$2b$10$QJ8YnBtqOWHjkIyBxPu.8K9QxQxQxQxQxQxQxQxQxQxQxQxQxQxX', -- hash of "pirate123"
                200
            );
        END IF;

        -- Deduct coins if sufficient, then insert stake
        BEGIN
            UPDATE accounts SET coins = coins - picked_amount
            WHERE username = picked_username AND coins >= picked_amount;

            IF FOUND THEN
                INSERT INTO stakes (username, contestant_id, amount)
                VALUES (picked_username, picked_contestant, picked_amount);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- ignore row if something fails (e.g., foreign key removed or coins too low)
        END;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

SELECT populate_random_stakes();

